# 공간 복잡도 예시: Python 3에서 실행 가능한 코드
def duplicate(items):
    copied = list(items)
    return len(copied)
print(duplicate([1, 2, 3]))

# 최선/평균/최악 케이스 예시: Python 3에서 실행 가능한 코드
def find_first_even(nums):
    for i, x in enumerate(nums):
        if x % 2 == 0:
            return i
print(find_first_even([2, 3, 5]), find_first_even([1, 3, 6]))

