# 분할 정복 예시: Python 3에서 실행 가능한 코드
def sum_dc(arr):
    if len(arr) <= 1:
        return sum(arr)
    mid = len(arr) // 2
    return sum_dc(arr[:mid]) + sum_dc(arr[mid:])
print(sum_dc([1, 2, 3, 4]))

# 탑다운 DP 예시: Python 3에서 실행 가능한 코드
from functools import lru_cache
@lru_cache(None)
def fib(n):
    return n if n < 2 else fib(n-1) + fib(n-2)
print(fib(7))

# 백트래킹 예시: Python 3에서 실행 가능한 코드
result = []
def pick(path):
    if len(path) == 2:
        result.append(path[:]); return
    for x in [1, 2, 3]:
        if x not in path:
            pick(path + [x])
pick([])
print(result[:3])

