# 퀵 정렬 예시: Python 3에서 실행 가능한 코드
def quick(a):
    if len(a) <= 1: return a
    p = a[0]
    return quick([x for x in a[1:] if x <= p]) + [p] + quick([x for x in a[1:] if x > p])
print(quick([3, 1, 4, 2]))

# 위상 정렬 예시: Python 3에서 실행 가능한 코드
from collections import deque
graph = {0:[1], 1:[2], 2:[]}
indeg = [0,1,1]
q = deque([0]); order = []
while q:
    v = q.popleft(); order.append(v)
    for nxt in graph[v]:
        indeg[nxt] -= 1
        if indeg[nxt] == 0: q.append(nxt)
print(order)

# BFS(너비 우선 탐색) 예시: Python 3에서 실행 가능한 코드
from collections import deque
g = {0:[1,2], 1:[3], 2:[], 3:[]}
q = deque([0]); seen = {0}; order = []
while q:
    v = q.popleft(); order.append(v)
    for n in g[v]:
        if n not in seen:
            seen.add(n); q.append(n)
print(order)

# DFS(깊이 우선 탐색) 예시: Python 3에서 실행 가능한 코드
g = {0:[1,2], 1:[3], 2:[], 3:[]}
seen = set(); order = []
def dfs(v):
    seen.add(v); order.append(v)
    for n in g[v]:
        if n not in seen: dfs(n)
dfs(0)
print(order)

# 다익스트라 알고리즘 예시: Python 3에서 실행 가능한 코드
import heapq
g = {0:[(1,2),(2,5)], 1:[(2,1)], 2:[]}
dist = {0:0}; pq = [(0,0)]
while pq:
    d,v = heapq.heappop(pq)
    if d != dist[v]: continue
    for n,w in g[v]:
        if d+w < dist.get(n, 10**9):
            dist[n] = d+w; heapq.heappush(pq, (d+w,n))
print(dist[2])

# 플로이드-워셜 알고리즘 예시: Python 3에서 실행 가능한 코드
INF = 10**9
d = [[0,3,INF],[INF,0,1],[2,INF,0]]
for k in range(3):
    for i in range(3):
        for j in range(3):
            d[i][j] = min(d[i][j], d[i][k] + d[k][j])
print(d[0][2])

# 유니온-파인드 예시: Python 3에서 실행 가능한 코드
parent = list(range(4))
def find(x):
    if parent[x] != x: parent[x] = find(parent[x])
    return parent[x]
def union(a,b): parent[find(b)] = find(a)
union(0, 1)
print(find(0) == find(1))

# 최장 증가 부분 수열(LIS) 예시: Python 3에서 실행 가능한 코드
arr = [10, 20, 10, 30]
dp = [1] * len(arr)
for i in range(len(arr)):
    for j in range(i):
        if arr[j] < arr[i]: dp[i] = max(dp[i], dp[j] + 1)
print(max(dp))

# 유클리드 호제법 예시: Python 3에서 실행 가능한 코드
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
print(gcd(48, 18))

# 해시 충돌 예시: Python 3에서 실행 가능한 코드
buckets = {}
for word in ["ad", "bc"]:
    key = sum(map(ord, word)) % 10
    buckets.setdefault(key, []).append(word)
